#include "commands.hpp"
// The table of the compiler, so that both always agree.
#include "compiler_internal.hpp"

#include <unordered_map>

namespace blitz::recompiler {
	namespace {
		std::vector<command> build()
		{
			std::vector<command> list;
			for (auto const& e : blitz::compiler_detail::builtins) {
				std::string params = e.params;
				list.push_back({ e.name, e.symbol, e.ret, params, std::vector<double>(std::begin(e.defaults), std::end(e.defaults)) });
			}
			// Commands that the compiler handles as statements, and that the original had as commands.
			list.push_back({ "end", "bb_end", 'v', "", {} });
			return list;
		}

		std::unordered_map<std::string, size_t> index(std::vector<command> const& list)
		{
			std::unordered_map<std::string, size_t> m;
			for (size_t i = 0; i < list.size(); i++) {
				m.emplace(list[i].name, i);
			}
			return m;
		}
	} // namespace

	std::vector<command> const& all_commands()
	{
		static const std::vector<command> list = build();
		return list;
	}

	command const* find_command(std::string const& name)
	{
		static const auto idx = index(all_commands());
		auto              it  = idx.find(name);
		return it == idx.end() ? nullptr : &all_commands()[it->second];
	}
} // namespace blitz::recompiler
